package com.ansh.bank.beneficiary.service;
import java.util.*; import com.ansh.bank.common.config.SeedData; import com.ansh.bank.beneficiary.dto.BeneficiaryDtos.*; import org.springframework.stereotype.Service;
/** Manage recipient creation and verification. */ @Service public class BeneficiaryService { private final SeedData d; public BeneficiaryService(SeedData d){this.d=d;} /** List recipients. */ public List<Response> all(){return d.beneficiaries.stream().map(this::map).toList();} /** Add an unverified recipient. */ public Response add(CreateRequest r){var b=new SeedData.Beneficiary("ben-"+UUID.randomUUID(),r.name(),r.accountNumber(),r.bank(),"PENDING");d.beneficiaries.add(b);return map(b);} /** Verify a recipient. */ public Response verify(String id){for(int i=0;i<d.beneficiaries.size();i++){var b=d.beneficiaries.get(i);if(b.id().equals(id)){var n=new SeedData.Beneficiary(b.id(),b.name(),b.accountNumber(),b.bank(),"VERIFIED");d.beneficiaries.set(i,n);return map(n);}}throw new IllegalArgumentException("Beneficiary not found");} private Response map(SeedData.Beneficiary b){return new Response(b.id(),b.name(),b.accountNumber(),b.bank(),b.status());} }
